from pathlib import Path
import hashlib,json,sqlite3

home=Path.home()
root=home/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
models=root/"models"
out={"models_exists":models.exists(),"files":[],"units":[]}
if models.exists():
    for p in sorted(models.rglob("*")):
        if p.is_file() and len(p.relative_to(models).parts)<=3:
            item={"path":str(p),"size":p.stat().st_size}
            if p.name in {"supervisor.py","CONFIG.json","runtime.sqlite"}:
                item["sha256"]=hashlib.sha256(p.read_bytes()).hexdigest()
            out["files"].append(item)
units=home/".config/systemd/user"
if units.exists():
    for p in sorted(units.glob("prediction-*")):
        n=p.name
        if "a2z" in n or "codex" in n:
            out["units"].append({"name":n,"is_symlink":p.is_symlink(),"target":str(p.resolve()) if p.is_symlink() else None})
dbp=models/"runtime.sqlite"
if dbp.exists():
    db=sqlite3.connect("file:"+str(dbp)+"?mode=ro",uri=True)
    try:
        task=db.execute("select status,attempt,run,thread from tasks where id=?",( "A2Z-V4-SOL-BUILD-20261007-R4", )).fetchone()
        tr=db.execute("select state,reason,attempt,checkpoint,next_action,stamp,retry from transitions where task=? order by seq desc limit 1",( "A2Z-V4-SOL-BUILD-20261007-R4", )).fetchone()
        out["task_row"]=task
        out["transition_row"]=tr
    finally:
        db.close()
print("E123_RUNTIME "+json.dumps(out,separators=(",",":"),default=str),flush=True)
